/**
 * Returns the length of the longest strictly increasing subsequence.
 * @param {number[]} arr
 * @returns {number}
 */
function lis(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return 0;

// tails[i] – minimal possible tail of an increasing subsequence of length i+1
  const tails = [];

for (const x of arr) {
    // binary search for the first element >= x
    let lo = 0, hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    // lo is the position to replace / append
    tails[lo] = x;
  }

return tails.length;
}
