/**
 * Evaluates an arithmetic expression containing integers,
 * + - * / operators and parentheses.
 * No use of eval or Function.
 *
 * @param {string} s – expression string
 * @returns {number} – computed value
 */
function evalExpr(s) {
  // remove spaces
  const str = s.replace(/\s+/g, '');
  let i = 0;

const peek = () => str[i];
  const getNumber = () => {
    let start = i;
    while (i < str.length && /[0-9]/.test(str[i])) i++;
    return Number(str.slice(start, i));
  };

// factor → number | '(' expr ')' | ('+'|'-') factor   (unary plus/minus)
  const factor = () => {
    const ch = peek();
    if (ch === '(') {
      i++; // '('
      const val = expr();
      if (peek() !== ')') throw new Error('Mismatched parentheses');
      i++; // ')'
      return val;
    }
    if (ch === '+' || ch === '-') {
      const sign = ch === '+' ? 1 : -1;
      i++;
      return sign * factor();
    }
    return getNumber();
  };

// term → factor { ('*'|'/') factor }
  const term = () => {
    let value = factor();
    while (i < str.length) {
      const op = peek();
      if (op !== '*' && op !== '/') break;
      i++;
      const right = factor();
      value = op === '*' ? value * right : value / right;
    }
    return value;
  };

// expr → term { ('+'|'-') term }
  const expr = () => {
    let value = term();
    while (i < str.length) {
      const op = peek();
      if (op !== '+' && op !== '-') break;
      i++;
      const right = term();
      value = op === '+' ? value + right : value - right;
    }
    return value;
  };

const result = expr();
  if (i !== str.length) throw new Error('Unexpected characters');
  return result;
}
