function toWordsRu(n) {
  if (!Number.isInteger(n) || n < 0 || n > 999) return '';

const units = [
    'ноль','один','два','три','четыре',
    'пять','шесть','семь','восемь','девять'
  ];
  const teens = [
    'десять','одиннадцать','двенадцать','тринадцать','четырнадцать',
    'пятнадцать','шестнадцать','семнадцать','восемнадцать','девятнадцать'
  ];
  const tens = [
    '','', // 0‑9 not used here
    'двадцать','тридцать','сорок','пятьдесят',
    'шестьдесят','семьдесят','восемьдесят','девяносто'
  ];
  const hundreds = [
    '','сто','двести','триста','четыреста',
    'пятьсот','шестьсот','семьсот','восемьсот','девятьсот'
  ];

if (n === 0) return units[0];

const h = Math.floor(n / 100);
  const t = Math.floor((n % 100) / 10);
  const u = n % 10;

let parts = [];

if (h) parts.push(hundreds[h]);

if (t === 1) {
    parts.push(teens[u]); // 10‑19
  } else {
    if (t) parts.push(tens[t]);
    if (u) parts.push(units[u]);
  }

return parts.join(' ');
}
```

Функция собирает части числа: сотни, десятки (учитывая 10‑19) и единицы, соединяя их пробелом. Возвращает пустую строку, если вход вне диапазона 0‑999.
